  "descriptionTH": "เซรั่มเรตินอลแบบห่อหุ้มที่มีเซราไมด์ ไนอาซินาไมด์ ลิโคคาลโคน และเทคโนโลยี MVE สำหรับปลดปล่อยแบบค่อยเป็นค่อยไป แก้ไขรอยดำหลังสิว พื้นผิวไม่สม่ำเสมอ การห่อหุ้มลดการระคายเคือง",
  "bestFor": "damaged barrier, dry, oily, combination, dull skin, mature skin, fine lines. Caution: avoid during pregnancy",
  "bestForTH": "ผิวแบเรียร์เสีย, ผิวแห้ง, ผิวมัน, ผิวผสม, ผิวหมองคล้ำ, ผิวมีริ้วรอย, ริ้วรอยตื้น. ระวัง: ห้ามใช้ระหว่างตั้งครรภ์",
  "howOften": "PM, start 2-3x/week, gradually increase to nightly",
