  "bestFor": "sensitive, acne-prone, dullness, dark spots, uneven tone, brightening, beginner vitamin C",
  "bestForTH": "ผิวแพ้ง่าย, ผิวเป็นสิว, ผิวหมองคล้ำ, จุดด่างดำ, สีผิวไม่สม่ำเสมอ, ผิวกระจ่างใส, ผู้เริ่มใช้วิตามินซี",
