  "fragranceFree": false,
  "alcoholFree": true,
  "eoFree": false,
  "activeIngredients": [
   "centella",
   "niacinamide",
   "peptides",
   "panthenol",
   "madecassoside"
  ],
  "description": "The renewed successor to the Centella Green Level Buffet Serum. A high-dose centella asiatica (~34,685 ppm, TECA + CICASOME nano-delivery) serum with niacinamide, four palmitoyl peptides, adenosine and Ceramide NP to rapidly soothe redness, refine texture and support the barrier. Note: this scented version contains bergamot, pine, rosemary and lavender oils, so it is not fragrance-/EO-free — an Unscented version exists for sensitive skin.",
  "descriptionTH": "รุ่นปรับสูตรที่มาแทน Centella Green Level Buffet Serum เซรั่มใบบัวบกเข้มข้น (~34,685 ppm สูตร TECA + CICASOME) ผสมไนอาซินาไมด์ เปปไทด์ 4 ชนิด อะดีโนซีน และ Ceramide NP ช่วยลดรอยแดงอย่างรวดเร็ว ปรับผิวเรียบเนียนและเสริมเกราะผิว หมายเหตุ: สูตรนี้มีน้ำมันเบอร์กามอต/สน/โรสแมรี/ลาเวนเดอร์ จึงไม่ปราศจากน้ำหอม/น้ำมันหอมระเหย (มีสูตร Unscented สำหรับผิวบอบบาง)",
  "bestFor": "redness, dullness, uneven skin tone, fine lines, dry skin, oily skin, combination skin",
  "bestForTH": "ผิวแดงง่าย, ผิวหมองคล้ำ, ผิวสีไม่สม่ำเสมอ, ริ้วรอยเล็ก, ผิวแห้ง, ผิวมัน, ผิวผสม",
  "howOften": "After cleansing and toning, apply 2-3 pumps to face and neck and pat in, before moisturiser. AM + PM.",
  "howOftenTH": "หลังล้างหน้าและโทนเนอร์ กด 2-3 ปั๊มลงบนใบหน้าและลำคอ ตบเบา ๆ ให้ซึม ก่อนบำรุงด้วยครีม เช้า-เย็น",
  "doNotCombine": "Niacinamide + peptides are broadly compatible. Avoid same-step layering with strong low-pH AHA/BHA or pure vitamin C to limit irritation; contains fragrant essential oils, so caution on reactive skin (choose the Unscented version if very sensitive).",
  "doNotCombineTH": "ไนอาซินาไมด์ + เปปไทด์ใช้ร่วมกับสารอื่นได้กว้าง เลี่ยงใช้ร่วมขั้นตอนเดียวกับ AHA/BHA ค่า pH ต่ำหรือวิตามินซีบริสุทธิ์เพื่อลดการระคาย มีน้ำมันหอมระเหย ควรระวังในผิวไว (เลือกสูตร Unscented หากผิวบอบบางมาก)",
  "medicubeMode": "None",
