  "doNotCombine": "Do not use the same night as retinal/retinol, benzoyl peroxide or another AHA/BHA exfoliant. Avoid same-step layering with pure vitamin C. Contains lavender + tea tree oils — caution on reactive or barrier-damaged skin.",
