  "eoFree": true,
  "activeIngredients": [
   "galactomyces"
  ],
  "description": "A two-ingredient fragrance-free ferment essence delivering 60% galactomyces ferment filtrate — the yeast-derived \"Pitera\" family ingredient linked in published work to antioxidant activity, increased hyaluronan production and barrier-protein support, with some brightening effect on dull or uneven tone. Note: galactomyces ferments are not fungal-acne-safe and can trigger reactions in malassezia-sensitive skin.",
  "descriptionTH": "เอสเซนส์เฟอร์เมนต์ปราศจากน้ำหอมเพียง 2 ส่วนผสม ให้กาแลคโตไมซิสเฟอร์เมนต์ฟิลเตรต 60% (กลุ่มเดียวกับ Pitera) มีงานวิจัยด้านสารต้านอนุมูลอิสระ การเพิ่มไฮยาลูโรแนน และช่วยผิวหมองคล้ำ หมายเหตุ: ไม่เหมาะกับผิวที่แพ้เชื้อรา (fungal acne)",
  "bestFor": "dullness, uneven skin tone, dehydrated skin, barrier repair, normal skin, glass skin",
  "bestForTH": "ผิวหมองคล้ำ, สีผิวไม่สม่ำเสมอ, ผิวขาดน้ำ, ฟื้นฟูเกราะป้องกันผิว, ผิวกระจก",
  "howOften": "AM + PM. After toner, apply 2-3 drops and press into the skin before serum. Introduce gradually if ferment-sensitive.",
  "howOftenTH": "เช้าและกลางคืน หลังโทนเนอร์ หยด 2-3 หยดแล้วตบให้ซึม ค่อยๆ เริ่มหากไม่เคยใช้เฟอร์เมนต์",
  "doNotCombine": "No direct active conflicts. Not recommended for fungal-acne (malassezia) prone skin. Introduce slowly if new to ferments.",
  "doNotCombineTH": "ไม่ขัดกับสารสำคัญโดยตรง ไม่แนะนำสำหรับผิวที่มีปัญหาเชื้อรา (malassezia)",
  "medicubeMode": "Booster",
  "imageUrl": "https://incidecoder-content.storage.googleapis.com/33644e14-acc2-4dd0-9beb-bdba32cba808/products/mixsoon-galactomyces-ferment-essence/mixsoon-galactomyces-ferment-essence_front_photo_original.jpeg",
