  "howOften": "AM only",
  "howOftenTH": "เฉพาะตอนเช้า",
  "description": "Round Lab's tone-up sunscreen (SPF50+ PA++++) — a hybrid formula pairing chemical filters (Ethylhexyl Methoxycinnamate, Ethylhexyl Salicylate) with physical Zinc Oxide and Titanium Dioxide. Iron oxides and calamine give a soft tone-up that brightens and blurs uneven tone with a dewy, no-heavy-cast finish, while peach extract, panthenol and allantoin condition the skin. The tone-up companion to the clear 1025 Dokdo Sun Cream.",
  "descriptionTH": "ครีมกันแดดสูตรโทนอัพจาก Round Lab (SPF50+ PA++++) เนื้อไฮบริดที่ผสานสารกันแดดแบบเคมี (Ethylhexyl Methoxycinnamate, Ethylhexyl Salicylate) กับแบบกายภาพ Zinc Oxide และ Titanium Dioxide พร้อมเม็ดสีไอรอนออกไซด์และคาลาไมน์ที่ช่วยปรับผิวให้กระจ่างใส กลบรอยไม่สม่ำเสมอ ให้ฟินิชฉ่ำวาวไม่ทิ้งคราบขาว เสริมด้วยสารสกัดพีช แพนทีนอล และอัลลันโทอินบำรุงผิว เป็นคู่โทนอัพของ 1025 Dokdo Sun Cream สูตรใส",
  "doNotCombine": "Apply as the final step in your morning routine",
  "doNotCombineTH": "ใช้เป็นขั้นตอนสุดท้ายของรูทีนตอนเช้า",
  "medicubeMode": "None",
  "makeupPrep": true,
  "ingredients": "Purified Water, Cyclopentasiloxane, Ethylhexyl Methoxycinnamate, Cyclohexasiloxane, Zinc Oxide (CI 77947), Ethylhexyl Salicylate, Butylene Glycol, Titanium Dioxide (CI 77891), Lauryl PEG-9 Polydimethylsiloxyethyl Dimethicone, Dipropylene Glycol, Ethylhexyl Palmitate, Polymethylsilsesquioxane, Dimethicone/Vinyl Dimethicone Crosspolymer, Caprylyl Methicone, Peach Extract, Cetyl PEG/PPG-10/1 Dimethicone, Dimethicone, Methyl Methacrylate Crosspolymer, Magnesium Sulfate, Disteardimonium Hectorite, Panthenol, Vinyl Dimethicone/Methicone Silsesquioxane Crosspolymer, C30-45 Alkyl Cetearyl Dimethicone Crosspolymer, Aluminum Hydroxide, Stearic Acid, Caprylyl Glycol, Glyceryl Caprylate, Calamine, Triethoxycaprylylsilane, Allantoin, Tocopherol, 1,2-Hexanediol, Yellow Iron Oxide (CI 77492), Red Iron Oxide (CI 77491)",
  "sourceUrl": "https://incidecoder.com/products/round-lab-365-tone-up-sun-cream",
