  "bestForTH": "ผิวธรรมดาถึงผิวผสม, เสริมเกราะป้องกันผิว, ให้ความชุ่มชื้นแบบบางเบา, เหมาะกับอากาศร้อนชื้น, รูทีนปราศจากน้ำหอม",
  "howOften": "AM and PM",
  "howOftenTH": "เช้าและกลางคืน",
  "description": "The lighter-weight version of SKINTIFIC's 5X Ceramide barrier gel — the same five-ceramide barrier complex (NP, AP, NS, AS, EOP) with phytosphingosine and hydrogenated lecithin, in a fast-absorbing gel for normal, combination or oily skin and humid climates. Soothed with bisabolol and ginger, with green-tea EGCG and ascorbyl palmitate for antioxidant support. Unlike the richer Barrier Repair Moisture Gel, this Light Texture formula is fragrance-free and contains NO essential oils.",
  "descriptionTH": "เวอร์ชันเนื้อบางเบาของเจลเสริมเกราะผิว 5X Ceramide จาก SKINTIFIC — ให้เซราไมด์ครบ 5 ชนิด (NP, AP, NS, AS, EOP) พร้อมไฟโตสฟิงโกซีนและไฮโดรจีเนเต็ดเลซิติน ในเนื้อเจลซึมไว เหมาะกับผิวธรรมดา ผิวผสม หรือผิวมันและอากาศร้อนชื้น ปลอบผิวด้วยบิสอะโบลอลและขิง เสริมสารต้านอนุมูลอิสระจากชาเขียว (EGCG) และแอสคอร์บิลปาล์มิเตท ต่างจากสูตร Barrier Repair เนื้อเข้มข้น สูตร Light Texture นี้ปราศจากน้ำหอมและไม่มีน้ำมันหอมระเหย",
  "doNotCombine": "Gentle enough to layer with most actives; apply after serums, before sunscreen (AM)",
  "doNotCombineTH": "อ่อนโยนพอที่จะใช้ร่วมกับสารบำรุงส่วนใหญ่ได้ ทาหลังเซรั่ม และก่อนครีมกันแดด (ตอนเช้า)",
  "medicubeMode": "None",
  "ingredients": "Aqua, PEG-8, Erythritol, Butylene Glycol, Dimethicone, Pentylene Glycol, Propanediol, Glycerin, Ammonium Acryloyldimethyltaurate/Beheneth-25 Methacrylate Crosspolymer, 1,2-Hexanediol, Hydroxyacetophenone, Sodium Polyacryloyldimethyl Taurate, Ceramide NP, Xanthan Gum, Bisabolol, Tetraselmis Suecica Extract, Hydroxyphenyl Propamidobenzoic Acid, Ceramide AP, Ceramide NS, Lactic Acid, Potassium Sorbate, Zingiber Officinale (Ginger) Root Extract, Ascorbyl Palmitate, Ceramide AS, Ceramide EOP, Dimethicone/Vinyl Dimethicone Crosspolymer, Arginine, Sodium Lauroyl Lactylate, Octyldodecanol, Diglucosyl Gallic Acid, Hydrolyzed Algae Extract, Hydrogenated Lecithin, Bioflavonoids, PPG-26-Buteth-26, PEG-40 Hydrogenated Castor Oil, Diisostearyl Malate, Epigallocatechin Gallatyl Glucoside, Ethoxydiglycol, Lecithin, Sodium Benzoate, Polyglyceryl-10 Stearate, Disodium EDTA, Sucrose Stearate, Phytosphingosine, Hexyldecanol, Caprylic/Capric Triglyceride",
