  "doNotCombineTH": "มิสต์เสริมเกราะผิว ฉีดบนผิวเปล่าหรือทับเมกอัพ หรือฉีดใส่ฝ่ามือแล้วกดลงบนผิวแบบเซรั่ม ใช้ร่วมกับทุกอย่างได้ ไม่มีข้อห้าม",
