  "description": "The antioxidant counterpart to La Glace's barrier mist: kombucha (black-tea ferment) plus a Pollustop-style anti-pollution complex, charcoal, licorice, rose and green-tea extracts, copper tripeptide, onsen water, ceramide NP and polyglutamic acid to shield tired, city-stressed skin from PM2.5, smoke and UV while replenishing moisture. Use as a refreshing prep mist or press-in serum. Fragrance-, alcohol- and essential-oil-free.",
  "descriptionTH": "มิสต์คู่แฝดสูตรต้านอนุมูลอิสระของลากลาส ด้วยคอมบูฉะ (หมักชาดำ) และคอมเพล็กซ์กันมลภาวะ ชาร์โคล ชะเอมเทศ สารสกัดกุหลาบและชาเขียว คอปเปอร์ไตรเปปไทด์ น้ำแร่ออนเซ็น เซราไมด์ NP และโพลีกลูตามิกแอซิด ช่วยปกป้องผิวที่อ่อนล้าจาก PM2.5 ควัน และแสงแดด พร้อมเติมความชุ่มชื้น ใช้เป็นมิสต์เตรียมผิวหรือกดแบบเซรั่ม ปราศจากน้ำหอม แอลกอฮอล์ และน้ำมันหอมระเหย",
  "bestFor": "dull & tired skin, pollution-exposed, dehydrated, normal",
  "bestForTH": "ผิวหมองคล้ำและอ่อนล้า, ผิวเผชิญมลภาวะ, ผิวขาดน้ำ, ผิวปกติ",
  "howOften": "AM and PM (reapply anytime)",
  "howOftenTH": "เช้าและกลางคืน (เติมได้ตลอดวัน)",
  "doNotCombine": "Antioxidant/anti-pollution barrier mist — spritz over bare skin or makeup, or press in as a serum. Layers with everything; no conflicts.",
  "doNotCombineTH": "มิสต์เสริมเกราะผิวต้านอนุมูลอิสระและมลภาวะ ฉีดบนผิวเปล่าหรือทับเมกอัพ หรือกดแบบเซรั่ม ใช้ร่วมกับทุกอย่างได้ ไม่มีข้อห้าม",
