  "descriptionTH": "เอสเซนส์ปลอบประโลมและเติมความชุ่มชื้น ด้วยเซนเทลลา เบาบับ เอเดลไวส์ ต้นคืนชีพ (Anastatica) ไฮยาลูรอนหลายชนิด แพนทีนอล สควาเลน และเซราไมด์ 3 เติมความชุ่มชื้นได้ดี แต่มีน้ำมันเบอร์กามอตที่ไวต่อแสง (พร้อมลิโมนีน/ลินาลูล) จึงไม่ปราศจากน้ำหอมและควรใช้กลางคืนพร้อมทากันแดดกลางวัน",
