  "howOftenTH": "กลางคืน เช็ดบนผิวที่ล้างแล้วเมื่อจำเป็น และทา SPF ตอนกลางวัน",
  "doNotCombine": "Alcohol + BHA + phototoxic bergamot oil — don't stack with other exfoliants/retinoids, don't use before sun, avoid on reactive skin.",
